require "net/http"
require "uri"

def req(method, path, body: nil)
  uri = URI("http://127.0.0.1:18080" + path)
  http = Net::HTTP.new(uri.host, uri.port)
  request_class = { "GET" => Net::HTTP::Get, "PUT" => Net::HTTP::Put, "DELETE" => Net::HTTP::Delete }.fetch(method)
  req = request_class.new(uri.request_uri)
  req.body = body if body
  res = http.request(req)
  [res.code, res.body]
end

